import { computed,onBeforeUnmount,onMounted,reactive,ref } from 'vue'; import { ElMessage,ElMessageBox } from 'element-plus'; import { useRoute,useRouter } from 'vue-router'; import type { GuidanceAssetDto,GuidanceContentDto,GuidanceValidationResultDto,GuidanceVersionDto } from '@home-rehab-motion/shared-contract'; import type { TrainingActionType } from '@home-rehab-motion/shared-types'; import GuidanceAssetField from '@/components/GuidanceAssetField.vue'; import { createGuidance,getGuidanceDetail,getGuidanceDraft,getGuidanceVersions,publishGuidance,rollbackGuidance,saveGuidanceDraft,validateGuidance } from '@/services/guidance';
const route=useRoute();const router=useRouter();const patientCheckText=ref('未核验');const isEdit=computed(()=>Boolean(route.params.id));const editId=computed(()=>Number(route.params.id));const saving=ref(false);const publishing=ref(false);const validation=ref<GuidanceValidationResultDto>();const versions=ref<GuidanceVersionDto[]>([]);const publishedVersion=ref<number>();const operationState=reactive<{kind:'idle'|'saving'|'success'|'warning'|'error';text:string}>({kind:'idle',text:'尚未保存任何改动'});const asset=():GuidanceAssetDto=>({url:''});const id=(prefix:string)=>`${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
const form=reactive<any>({actionType:'' as TrainingActionType|'',title:'',briefInstruction:'',estimatedMinutes:3,coverImage:asset(),trainingSafetyNotice:'',video:{asset:asset(),fallbackText:''},steps:[],shootingRequirements:[],commonMistakes:[]});
const coverDefaults=[{type:'abdominal_crunch',label:'缩腹运动',asset:{url:'/guidance-defaults/cover-abdominal-crunch.png',mimeType:'image/png'}},{type:'pelvic_tilt',label:'骨盆倾斜',asset:{url:'/guidance-defaults/cover-pelvic-tilt.png',mimeType:'image/png'}},{type:'knee_rotation',label:'膝关节旋转',asset:{url:'/guidance-defaults/cover-knee-rotation.png',mimeType:'image/png'}}] as const;function applyCoverDefault(item:typeof coverDefaults[number]){form.coverImage={...item.asset};}
const referenceSuggestions:Partial<Record<TrainingActionType,{source:string;steps:Array<{id:string;title:string;description:string;altText:string;image:GuidanceAssetDto}>}>>={abdominal_crunch:{source:'教学视频_缩腹运动_0050-0080.mp4（30 秒参考片段）',steps:[{id:'reference-abdominal-1',title:'仰卧屈膝准备',description:'平卧屈膝、双脚踩稳地面，双手轻放在腹部，放松肩颈。',altText:'缩腹运动参考视频中训练者平卧屈膝的准备姿势截图。',image:{url:'/guidance-defaults/reference-steps/abdominal_crunch-step-1.jpg',mimeType:'image/jpeg'}},{id:'reference-abdominal-2',title:'缓慢收紧腹部',description:'自然呼气时轻轻向内收紧腹部，保持肩背贴稳地面，避免憋气。',altText:'缩腹运动参考视频中平卧收紧腹部的重点截图。',image:{url:'/guidance-defaults/reference-steps/abdominal_crunch-step-2.jpg',mimeType:'image/jpeg'}},{id:'reference-abdominal-3',title:'放松并重复',description:'缓慢放松回到自然呼吸，保持平卧姿势稳定后再重复动作。',altText:'缩腹运动参考视频中平卧放松回位的截图。',image:{url:'/guidance-defaults/reference-steps/abdominal_crunch-step-3.jpg',mimeType:'image/jpeg'}}]},pelvic_tilt:{source:'教学视频_骨盆倾斜_0080-0140.mp4（60 秒参考片段）',steps:[{id:'reference-pelvic-1',title:'平卧屈膝准备',description:'平卧屈膝、双脚踩稳地面，肩颈和腰背保持放松。',altText:'骨盆倾斜参考视频中训练者平卧屈膝的准备姿势截图。',image:{url:'/guidance-defaults/reference-steps/pelvic_tilt-step-1.jpg',mimeType:'image/jpeg'}},{id:'reference-pelvic-2',title:'轻轻后倾骨盆',description:'呼气时轻轻收紧下腹，让腰背更贴近地面，动作不要急。',altText:'骨盆倾斜参考视频中平卧骨盆后倾的重点截图。',image:{url:'/guidance-defaults/reference-steps/pelvic_tilt-step-2.jpg',mimeType:'image/jpeg'}},{id:'reference-pelvic-3',title:'回到中立位置',description:'吸气后慢慢回到舒适的平卧中立位，避免用力顶起臀部。',altText:'骨盆倾斜参考视频中平卧回位的截图。',image:{url:'/guidance-defaults/reference-steps/pelvic_tilt-step-3.jpg',mimeType:'image/jpeg'}}]},knee_rotation:{source:'教学视频_膝关节旋转_0140-0218.mp4（78 秒参考片段）',steps:[{id:'reference-knee-1',title:'平卧屈膝准备',description:'平卧屈膝并拢，双脚踩地，双臂自然放在身体两侧。',altText:'膝关节旋转参考视频中训练者平卧屈膝的准备姿势截图。',image:{url:'/guidance-defaults/reference-steps/knee_rotation-step-1.jpg',mimeType:'image/jpeg'}},{id:'reference-knee-2',title:'双膝缓慢倾向一侧',description:'双膝一起缓慢倒向一侧，骨盆随动作自然转动，肩背尽量贴稳地面。',altText:'膝关节旋转参考视频中平卧双膝侧向倾倒的重点截图。',image:{url:'/guidance-defaults/reference-steps/knee_rotation-step-2.jpg',mimeType:'image/jpeg'}},{id:'reference-knee-3',title:'回正后换侧',description:'慢慢回到平卧中间位，再向另一侧重复，始终以舒适无痛为准。',altText:'膝关节旋转参考视频中平卧回正换侧的截图。',image:{url:'/guidance-defaults/reference-steps/knee_rotation-step-3.jpg',mimeType:'image/jpeg'}}]}};const referenceSuggestion=computed(()=>form.actionType?referenceSuggestions[form.actionType as TrainingActionType]:undefined);function applyReferenceSteps(){if(!referenceSuggestion.value)return;form.steps=referenceSuggestion.value.steps.map((step,index)=>({...step,order:index+1,image:{...step.image}}));operationState.kind='warning';operationState.text='已填入参考视频建议步骤，请检查后保存草稿；尚未发布给患者。';ElMessage.success('已将 3 个参考步骤写入当前编辑内容');}
const shootingDefaults=[{type:'angle',label:'拍摄角度',title:'正侧面拍摄',description:'手机放在身体正侧方，与平卧躯干保持平行。',altText:'训练者平卧在垫上，手机放在身体正侧方。',correctImage:{url:'/guidance-defaults/shooting-angle-side.png',mimeType:'image/png'}},{type:'framing',label:'入镜范围',title:'平卧全身完整入镜',description:'平卧后从头到脚都要拍到，四周留出适当空间。',altText:'训练者平卧时从头到脚完整出现在手机画面内。',correctImage:{url:'/guidance-defaults/shooting-framing-full-body.png',mimeType:'image/png'}},{type:'lighting',label:'光线',title:'光线充足、画面明亮',description:'让平卧身体处于明亮区域，避免背光和阴影遮挡。',altText:'训练者平卧在明亮区域，脸部和身体轮廓清晰。',correctImage:{url:'/guidance-defaults/shooting-lighting-bright.png',mimeType:'image/png'}}] as const;const navItems=computed(()=>[{key:'basic',label:'基础信息',count:basicComplete.value?'已完成':'待补充'},{key:'video',label:'教学视频',count:form.video.asset.url?'已上传':'待上传'},{key:'steps',label:'动作步骤',count:`${form.steps.length}/5`},{key:'shooting',label:'拍摄要求',count:`${form.shootingRequirements.length} 条`},{key:'mistakes',label:'常见错误',count:`${form.commonMistakes.length} 条`}]);const activeSection=ref('basic');const basicComplete=computed(()=>Boolean(form.title&&form.briefInstruction&&form.coverImage.url&&form.trainingSafetyNotice));const validationText=computed(()=>validation.value?(validation.value.valid?'发布检查已通过':`待补充 ${validation.value.errors.length} 项`):'尚未执行发布检查');function mediaUrl(url?:string){if(!url||/^https?:\/\//.test(url)||url.startsWith('data:'))return url||'';return url.startsWith('/')?url:`/${url}`;}function isVideoAsset(item?:GuidanceAssetDto){return Boolean(item?.mimeType?.startsWith('video/')||/\.(mp4|mov|m4v)(\?|$)/i.test(item?.url||''));}
let sectionObserver:IntersectionObserver|undefined;let contentScroller:HTMLElement|undefined;function syncActiveSection(){const sections=navItems.value.map(item=>document.getElementById(item.key)).filter((section):section is HTMLElement=>Boolean(section));const scrollerTop=contentScroller?.getBoundingClientRect().top||0;const current=sections.reduce<HTMLElement|undefined>((closest,section)=>section.getBoundingClientRect().top-scrollerTop<=150?section:closest,undefined);if(current)activeSection.value=current.id;}function observeSections(){sectionObserver?.disconnect();contentScroller=document.querySelector<HTMLElement>('.layout-main');const sections=navItems.value.map(item=>document.getElementById(item.key)).filter((section):section is HTMLElement=>Boolean(section));sectionObserver=new IntersectionObserver(entries=>{const visible=entries.filter(entry=>entry.isIntersecting).sort((a,b)=>a.boundingClientRect.top-b.boundingClientRect.top)[0];if(visible)activeSection.value=(visible.target as HTMLElement).id;},{root:contentScroller||null,rootMargin:'-96px 0px -58% 0px',threshold:[0,.1,.5]});sections.forEach(section=>sectionObserver?.observe(section));syncActiveSection();}function normalizeEditorCollections(){if(!Array.isArray(form.steps))form.steps=[];if(!Array.isArray(form.shootingRequirements))form.shootingRequirements=[];if(!Array.isArray(form.commonMistakes))form.commonMistakes=[];}function addStep(){normalizeEditorCollections();if(form.steps.length<5)form.steps.push({id:id('step'),order:form.steps.length+1,title:'',description:'',image:asset(),altText:''});}function applyShootingDefault(item: typeof shootingDefaults[number]){normalizeEditorCollections();const index=form.shootingRequirements.findIndex((requirement:any)=>requirement.type===item.type);const value={id:index>=0?form.shootingRequirements[index].id:id(`shooting-${item.type}`),type:item.type,title:item.title,description:item.description,correctImage:{...item.correctImage},altText:item.altText};if(index>=0)form.shootingRequirements.splice(index,1,value);else form.shootingRequirements.push(value);}function applyShootingTemplate(notify=true){shootingDefaults.forEach(applyShootingDefault);if(notify)ElMessage.success('已套用三项拍摄要求模板，可继续调整');}function addShooting(){normalizeEditorCollections();form.shootingRequirements.push({id:id('shooting'),type:'angle',title:'',description:'',correctImage:asset(),altText:''});}function addMistake(){normalizeEditorCollections();form.commonMistakes.push({id:id('mistake'),order:form.commonMistakes.length+1,title:'',mistakeDescription:'',correction:'',media:asset()});}function remove(list:any[],index:number){list.splice(index,1);list.forEach((item,i)=>{if('order'in item)item.order=i+1;});}function mistakeMediaKind(item:GuidanceAssetDto){return item?.mimeType?.startsWith('video/')?'video':'image';}function scrollTo(key:string){activeSection.value=key;document.getElementById(key)?.scrollIntoView({behavior:'smooth',block:'start'});}function apply(data:GuidanceContentDto){Object.assign(form,JSON.parse(JSON.stringify(data)));normalizeEditorCollections();publishedVersion.value=data.version;}function payload(){return JSON.parse(JSON.stringify(form));}
function errorText(error:any){const message=error?.response?.data?.message||error?.response?.data?.error||error?.message;return Array.isArray(message)?message.join('；'):message||'请求失败，请稍后重试';}async function saveDraft(){if(!form.actionType||!form.title){operationState.kind='warning';operationState.text='草稿未保存：请先填写动作类型和标题';ElMessage.warning(operationState.text);return false;}saving.value=true;operationState.kind='saving';operationState.text='正在保存草稿，患者端不会看到本次改动…';try{if(!isEdit.value){const created=await createGuidance(payload());await router.replace(`/guidance/${created.contentId}/edit`);apply(created);}else{apply(await saveGuidanceDraft(editId.value,payload()));}operationState.kind='success';operationState.text=`草稿已保存于 ${new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}，尚未发布给患者`;ElMessage.success('草稿保存成功');return true;}catch(error:any){operationState.kind='error';operationState.text=`草稿保存失败：${errorText(error)}`;ElMessage.error(operationState.text);return false;}finally{saving.value=false;}}async function runValidation(){const saved=await saveDraft();if(!saved||!isEdit.value)return false;try{validation.value=await validateGuidance(editId.value);if(validation.value.valid){operationState.kind='warning';operationState.text='发布检查已通过，尚未发布。请点击“发布患者可见版本”完成正式发布。';}else{operationState.kind='warning';operationState.text=`发布前还需补充 ${validation.value.errors.length} 项内容`;}return validation.value.valid;}catch(error:any){operationState.kind='error';operationState.text=`发布检查失败：${errorText(error)}`;return false;}}async function publish(){if(publishing.value||saving.value)return;publishing.value=true;operationState.kind='saving';operationState.text='正在保存草稿并执行发布检查…';try{const saved=await saveDraft();if(!saved)return;validation.value=await validateGuidance(editId.value);if(!validation.value.valid){operationState.kind='warning';operationState.text=`未发布：发布前还需补充 ${validation.value.errors.length} 项内容`;ElMessage.warning(operationState.text);return;}operationState.kind='