onMounted(async()=>{if(isEdit.value){try{apply(await getGuidanceDraft(editId.value));await loadVersions();}catch{ElMessage.error('草稿加载失败');}}else{addStep();addStep();addStep();applyShootingTemplate(false);}requestAnimationFrame(()=>{observeSections();contentScroller?.addEventListener('scroll',syncActiveSection,{passive:true});});});onBeforeUnmount(()=>{sectionObserver?.disconnect();contentScroller?.removeEventListener('scroll',syncActiveSection);});
